test('admitting a review to metadata lookup captures its source, member Credits, attribution and durations, and stores format 3 with one new revision and no receipt', async () => {
    const { guest, label, ids, rows } = await capturedAlbumFixture();
    const review = await create(), id = review.item.id, _id = new ObjectId(id), before = (await importCollection().findOne({ _id }))!;
    assert.equal('expectedTracklist' in review.item.draft.album, false); assert.ok(review.item.draft.tracks.every(track => !('artists' in track)));
    await admitLookup(id);
    const doc = (await importCollection().findOne({ _id }))!, [one, two, three] = before.catalogSource!.tracks.map(track => track.slotId);
    // The draft changed without an administrator receipt: the revision advances once, and the receipts are unchanged.
    assert.deepEqual([doc.draftVersion, doc.revision, doc.receipts], [3, before.revision + 1, before.receipts]);
    assert.ok(doc.updatedAt > before.updatedAt);
    const record = async (kind: 'artists' | 'organizations', recordId: ObjectId) => importCandidateRevision((await db().collection(kind).findOne({ _id: recordId }, { projection: importCandidateProjection }))!);
    const existing = { name: 'Existing Artist', musicBrainzId: ids.artist, revision: await record('artists', artist) };
    const capture = doc.catalogCapture!, albumKey = derivedEntryKey({ catalogReview: id, creditId: 'primary_artist' }), memberKey = (creditId: string) => derivedEntryKey({ catalogReview: id, slotId: one, creditId });
    assert.deepEqual(capture.album, { credits: [
        { creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', joinPhrase: null, entryKey: albumKey, subject: existing },
        { creditId: 'album_label', subjectType: 'organization', subjectId: String(label), role: 'label', joinPhrase: null, entryKey: null, subject: { name: 'Synthetic Label', musicBrainzId: ids.label, revision: await record('organizations', label) } }
    ], artistsComplete: true, label: 'first', expectedTracklist: rows });
    assert.deepEqual(capture.members.map(member => [member.slotId, member.attributionStatus, member.duration, member.artistsComplete]), [
        [one, 'documented', { durationMs: 61_234, durationPrecisionMs: 0 }, true], [two, 'unknown', { durationMs: 60_000, durationPrecisionMs: 1000 }, true], [three, null, null, false]]);
    assert.deepEqual(capture.members[0].credits, [
        { creditId: 'member_primary', subjectType: 'artist', subjectId: String(guest), role: 'primary', joinPhrase: ' & ', entryKey: memberKey('member_primary'), subject: { name: 'Synthetic Guest', musicBrainzId: ids.guest, revision: await record('artists', guest) } },
        { creditId: 'member_featured', subjectType: 'artist', subjectId: String(artist), role: 'featured', joinPhrase: null, entryKey: memberKey('member_featured'), subject: existing }
    ]);
    // The unmigrated member's valid legacy link is a legacy unspecified Credit, shown as no entry; malformed Credits are unreadable.
    assert.deepEqual(capture.members[1].credits?.map(value => [value.subjectId, value.role, value.entryKey, value.subject]), [[String(artist), 'legacyUnspecified', null, existing]]);
    assert.equal(capture.members[2].credits, null);
    assert.ok(capture.capturedAt instanceof Date);
    // The draft: Album entries rebuilt with the records' IDs (same keys), the label with its ID, the tracklist and member entries.
    const draft = doc.draft as CatalogReviewResponse['item']['draft'];
    assert.deepEqual(draft.album.artists, [{ key: albumKey, name: 'Existing Artist', role: 'primary', joinPhrase: null, musicBrainzId: ids.artist }]);
    assert.deepEqual(draft.album.label, { name: 'Synthetic Label', musicBrainzId: ids.label });
    assert.deepEqual(draft.album.expectedTracklist, rows);
    assert.deepEqual(draft.tracks.map(track => track.artists), [[
        { key: memberKey('member_primary'), name: 'Synthetic Guest', role: 'primary', joinPhrase: ' & ', musicBrainzId: ids.guest },
        { key: memberKey('member_featured'), name: 'Existing Artist', role: 'featured', joinPhrase: null, musicBrainzId: ids.artist }], [], []]);
    assert.deepEqual([draft.album.title, draft.tracks.map(track => [track.title, track.discNumber, track.trackNumber])], [(before.draft as typeof draft).album.title, (before.draft as typeof draft).tracks.map(track => [track.title, track.discNumber, track.trackNumber])]);
    // Everything else is untouched: the frozen source (it captured every disc already), evidence, manifest, analysis and suggestions.
    for (const key of ['catalogSource', 'catalogEvidence', 'manifest', 'analysis', 'suggestions', 'decisions', 'actorId', 'createdAt'] as const) assert.deepEqual(doc[key], before[key], key);
    // The detail shows the review-only values (the DTO allowlist) and never the capture; the review is still current and applicable.
    const read = await current(id), json = JSON.stringify(read);
    assert.deepEqual([read.item.draft.album.expectedTracklist, read.item.draft.tracks.map(track => track.artists?.length), read.item.sourceStatus, read.item.capabilities.apply], [rows, [2, 0, 0], 'current', true]);
    for (const sentinel of ['catalogCapture', 'capturedAt', 'artistsComplete', 'attributionStatus', 'durationPrecisionMs', 'legacyUnspecified']) assert.equal(json.includes(sentinel), false, sentinel);
});

test('a review whose source is not current is never admitted to metadata lookup, and nothing is stored', async () => {
    const replaced = new ObjectId();
    const changes: [string, () => Promise<unknown>][] = [
        ['an Album edit', () => db().collection('albums').updateOne({ _id: album }, { $set: { title: 'Edited elsewhere' } })],
        ['a member edit', () => db().collection('audioTracks').updateOne({ _id: second }, { $set: { title: 'Edited elsewhere' } })],
        ['a member Credit edit', () => db().collection('audioTracks').updateOne({ _id: first }, { $set: { credits: [{ creditId: 'added', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 0 }], attributionStatus: 'documented' } })],
        ['a media replacement', () => db().collection('audioTracks').updateOne({ _id: first }, { $set: { s3Key: `audio/${first}/${replaced}` } })],
        ['an expected tracklist change', () => db().collection('albums').updateOne({ _id: album }, { $set: { expectedTracklist: { source: 'musicbrainz', appliedAt: new Date(0), rows: [{ discNumber: 1, trackNumber: 1, title: 'Track 1', durationMs: null }] } } })],
        ['a membership change', () => db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [String(first)] } })],
        ['an unready member', () => db().collection('audioTracks').updateOne({ _id: second }, { $set: { publicationStatus: 'pending' } })],
        ['the Album deleted', () => db().collection('albums').deleteOne({ _id: album })]
    ];
    for (const [label, change] of changes) {
        const review = await create(), _id = new ObjectId(review.item.id), before = await importCollection().findOne({ _id });
        await change();
        await assert.rejects(admitLookup(review.item.id), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'), label);
        assert.deepEqual(await importCollection().findOne({ _id }), before, label);
        // Restore a creatable Album for the next case.
        await db().collection('albums').deleteMany({}); await db().collection('audioTracks').deleteMany({});
        await db().collection('albums').insertOne({ _id: album, title: 'Existing Album', releaseDate: { year: 2020 }, visibility: 'hidden', lifecycleStatus: 'ready', audioTrackIds: [String(first), String(second)], credits: [{ creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 0 }], attributionStatus: 'documented' });
        await db().collection('audioTracks').insertMany([first, second].map((trackId, index) => ({ _id: trackId, title: `Track ${index + 1}`, trackNumber: index + 1, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: String(trackId), albumId: String(album), visibility: 'public', mediaType: 'audio', duration: '1:00' })));
    }
    // A review already captured is checked again on every admission: a later source change refuses it without touching the capture.
    const review = await create(), _id = new ObjectId(review.item.id); await admitLookup(review.item.id);
    const captured = await importCollection().findOne({ _id });
    await db().collection('albums').updateOne({ _id: album }, { $set: { title: 'Edited after capture' } });
    await assert.rejects(admitLookup(review.item.id), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
    assert.deepEqual(await importCollection().findOne({ _id }), captured);
});

test('admission to metadata lookup is idempotent, also for two concurrent admissions, and refuses applied, newer and unreadable reviews', async () => {
    await capturedAlbumFixture();
    const review = await create(), _id = new ObjectId(review.item.id);
    const settled = await Promise.allSettled([admitLookup(review.item.id), admitLookup(review.item.id)]);
    assert.deepEqual(settled.map(value => value.status), ['fulfilled', 'fulfilled']);
    const captured = (await importCollection().findOne({ _id }))!;
    assert.equal(captured.draftVersion, 3);
    // Admitting again only checks: the stored capture, its time included, and the draft are unchanged.
    await admitLookup(review.item.id); assert.deepEqual(await importCollection().findOne({ _id }), captured);
    // A capture this release cannot read asks for a reload.
    for (const unreadable of [{ catalogCapture: null }, { 'catalogCapture.members': [] }, { 'catalogCapture.album': 'x' }]) {
        await importCollection().updateOne({ _id }, { $set: unreadable } as any);
        await assert.rejects(admitLookup(review.item.id), code('ADMIN_IMPORT_RELOAD_REQUIRED'), JSON.stringify(unreadable));
        await importCollection().replaceOne({ _id }, captured);
    }
    // So does a format-3 draft without its review-only values, and a newer format.
    await importCollection().updateOne({ _id }, { $unset: { 'draft.album.expectedTracklist': '' } });
    await assert.rejects(admitLookup(review.item.id), code('ADMIN_IMPORT_RELOAD_REQUIRED')); await importCollection().replaceOne({ _id }, captured);
    await importCollection().updateOne({ _id }, { $set: { draftVersion: 4 } });
    await assert.rejects(admitLookup(review.item.id), code('ADMIN_IMPORT_RELOAD_REQUIRED')); await importCollection().replaceOne({ _id }, captured);
    // A format-2 draft holding a track that is not an object is never converted into a format-3 review it could not edit.
    const malformed = await create(), malformedId = new ObjectId(malformed.item.id);
    await importCollection().updateOne({ _id: malformedId }, { $set: { 'draft.tracks.1': null } });
    const unconverted = await importCollection().findOne({ _id: malformedId });
    await assert.rejects(admitLookup(malformed.item.id), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    assert.deepEqual(await importCollection().findOne({ _id: malformedId }), unconverted);
    // An applied review is closed; a format-2 applied review is never converted.
    const applied = await apply(await current(review.item.id));
    await assert.rejects(admitLookup(applied.item.id), code('ADMIN_CATALOG_REVIEW_APPLIED'));
    const otherReview = await create(), otherId = new ObjectId(otherReview.item.id), closed = await apply(otherReview), stored = await importCollection().findOne({ _id: otherId });
    await assert.rejects(admitLookup(closed.item.id), code('ADMIN_CATALOG_REVIEW_APPLIED'));
    assert.deepEqual(await importCollection().findOne({ _id: otherId }), stored);
    // An import project is not a review.
    const legacy = await createAdminImport(String(actor), { operationId: randomUUID(), manifest: { rootLabel: 'Folder', files: [{ slotId: randomUUID(), filename: 'Song.mp3', relativePath: 'Song.mp3', byteLength: 1 }] } });
    await assert.rejects(admitLookup(legacy.item.id), code('ADMIN_CATALOG_REVIEW_NOT_FOUND'));
});

