test('per-path staleness: an administrator value saved since conflicts and writes nothing, an automatic value only yields on a path the save sends', async () => {
    let review = await create(); const id = review.item.id, _id = new ObjectId(id), [one, two] = review.item.draft.tracks;
    await admitLookup(id); review = await current(id);
    // Another administrator saves the title; a save still based on the old title conflicts and its sibling change is not written.
    const moved = await editCatalogReview(String(other), id, { ...mutation(review.item.revision), changes: [{ path: 'album.title', base: 'Existing Album', value: 'Other administrator title' }] });
    const before = await importCollection().findOne({ _id });
    await assert.rejects(save(moved, [{ path: `tracks.${one.slotId}.title`, base: one.title, value: 'Sibling change' }, { path: 'album.title', base: 'Existing Album', value: 'My title' }]), code('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.deepEqual(await importCollection().findOne({ _id }), before);
    // A save from before that administrator's receipt is refused whatever it changes.
    await assert.rejects(save(review, [{ path: `tracks.${one.slotId}.title`, base: one.title, value: 'Late change' }]), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    // Sending the value already saved is not stale.
    review = await save(moved, [{ path: 'album.title', base: 'Existing Album', value: 'Other administrator title' }]);
    // An automatic value (as metadata lookup writes one) is kept by a save of another path, and replaced only when the save sends it.
    await importCollection().updateOne({ _id }, { $set: { 'draft.album.title': 'Automatic title', 'draft.tracks.1.title': 'Automatic track', 'draftOrigins.album:title': 'automatic', [`draftOrigins.tracks:${two.slotId}:title`]: 'automatic' } } as any);
    review = await save(review, [{ path: `tracks.${one.slotId}.title`, base: one.title, value: 'Only this track' }]);
    let doc = (await importCollection().findOne({ _id }))!;
    assert.deepEqual([(doc.draft as typeof review.item.draft).album.title, (doc.draft as typeof review.item.draft).tracks.map(track => track.title)], ['Automatic title', ['Only this track', 'Automatic track']]);
    assert.deepEqual([doc.draftOrigins!['album:title'], doc.draftOrigins![`tracks:${two.slotId}:title`], doc.draftOrigins![`tracks:${one.slotId}:title`]], ['automatic', 'automatic', 'administrator']);
    review = await save(review, [{ path: 'album.title', base: 'Other administrator title', value: 'Replaces the automatic title' }]);
    doc = (await importCollection().findOne({ _id }))!;
    assert.deepEqual([(doc.draft as typeof review.item.draft).album.title, doc.draftOrigins!['album:title'], (doc.draft as typeof review.item.draft).tracks[1].title], ['Replaces the automatic title', 'administrator', 'Automatic track']);
});

test('the review size cap binds only editable values that grow: a large tracklist and member entries never block a title edit', async () => {
    const ids = Array.from({ length: 60 }, () => new ObjectId());
    await db().collection('audioTracks').insertMany(ids.map((trackId, index) => ({ _id: trackId, title: `Track ${index + 1}`, trackNumber: index + 1, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: String(trackId), albumId: String(album), visibility: 'public', mediaType: 'audio' })));
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: ids.map(String) } });
    let review = await create(); const _id = new ObjectId(review.item.id), before = await importCollection().findOne({ _id });
    // Growing every title past 48 KB is refused and writes nothing.
    await assert.rejects(save(review, review.item.draft.tracks.map(track => ({ path: `tracks.${track.slotId}.title`, base: track.title, value: '题'.repeat(300) }))), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), before);
    // A format-3 review holding a near-32 KB tracklist and 20 long member entries on each of two members stays editable.
    const artists = Array.from({ length: 20 }, (_, index) => ({ _id: new ObjectId(), name: `${'题'.repeat(190)} ${String(index).padStart(3, '0')}`, lifecycleStatus: 'ready' }));
    await db().collection('artists').insertMany(artists);
    const rows = Array.from({ length: 100 }, (_, index) => ({ discNumber: 1, trackNumber: index + 1, title: 'x'.repeat(250), durationMs: null }));
    assert.ok(Buffer.byteLength(JSON.stringify(rows)) > 31_000 && Buffer.byteLength(JSON.stringify(rows)) <= 32_768);
    const credits = artists.map((value, order) => ({ creditId: `artist_${order}`, subjectType: 'artist', subjectId: String(value._id), role: 'primary', order, joinPhrase: ' & ' }));
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [String(first), String(second)], expectedTracklist: { source: 'musicbrainz', appliedAt: new Date(0), rows } } });
    await db().collection('audioTracks').updateMany({ _id: { $in: [first, second] } }, { $set: { credits, attributionStatus: 'documented' } });
    review = await create(); await admitLookup(review.item.id); review = await current(review.item.id);
    assert.ok(draftBytes(review.item.draft) > 55_000, String(draftBytes(review.item.draft)));
    assert.deepEqual([review.item.draft.album.expectedTracklist?.length, review.item.draft.tracks.map(track => track.artists?.length)], [100, [20, 20]]);
    review = await save(review, [{ path: 'album.title', base: 'Existing Album', value: '题'.repeat(300) }, { path: `tracks.${review.item.draft.tracks[0].slotId}.title`, base: 'Track 1', value: 'Edited' }]);
    assert.deepEqual([review.item.draft.album.title, review.item.draft.tracks[0].title, review.item.draft.album.expectedTracklist?.length], ['题'.repeat(300), 'Edited', 100]);
});

test('review save bodies may reach 160 KB; other review bodies stay at 96 KB', async () => {
    const review = await create(), path = `/catalog-reviews/${review.item.id}`;
    // Between 96 and 160 KB the body is parsed and judged (each base is over a draft's size), never refused for its size.
    const between = await request(path, 'PATCH', { ...mutation(review.item.revision), changes: [{ path: 'album.title', base: 'b'.repeat(60_000), value: 'v'.repeat(60_000) }] });
    assert.deepEqual([between.status, await between.json()], [400, { code: 'ADMIN_IMPORT_INVALID_INPUT' }]);
    assert.equal((await request(path, 'PATCH', { ...mutation(review.item.revision), changes: [{ path: 'album.title', base: 'b'.repeat(170_000), value: '' }] })).status, 413);
    assert.equal((await request(`${path}/analyze`, 'POST', { ...mutation(review.item.revision), padding: 'p'.repeat(100_000) })).status, 413);
    assert.equal((await request('/catalog-reviews', 'POST', { ...(await createBody()), padding: 'p'.repeat(100_000) })).status, 413);
    // The larger save parser runs only after authentication and administrator checks: anyone else is refused before parsing.
    const stored = await importCollection().findOne({ _id: new ObjectId(review.item.id) });
    const raw = (body: string, access?: string) => fetch(base + '/api/admin/v1' + path, { method: 'PATCH', headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), 'Content-Type': 'application/json' }, body });
    assert.equal((await raw('{broken', userToken)).status, 403);
    assert.equal((await raw('{broken')).status, 401);
    assert.equal((await raw(JSON.stringify({ ...mutation(review.item.revision), changes: [{ path: 'album.title', base: 'b'.repeat(150_000), value: '' }] }), userToken)).status, 403);
    assert.deepEqual(await importCollection().findOne({ _id: new ObjectId(review.item.id) }), stored);
    // An ordinary save through the route is admitted.
    const saved = await request(path, 'PATCH', { ...mutation(review.item.revision), changes: [{ path: 'album.title', base: 'Existing Album', value: 'Saved over HTTP' }] });
    assert.equal(saved.status, 200); assert.equal((await saved.json()).item.draft.album.title, 'Saved over HTTP');
});

